begin;
create temporary table hr_theme_verification(check_name text,passed boolean);
alter table hr_theme_verification enable row level security;
do $test$
declare actor text:='999999999999999991'; other_actor text:='999999999999999992'; result jsonb; n integer; order_a uuid:='00000000-0000-4000-8000-000000001001'; order_b uuid:='00000000-0000-4000-8000-000000001002';
begin
 if exists(select 1 from users where user_id in(actor,other_actor)) or exists(select 1 from qiunai_staff where discord_id=actor) or exists(select 1 from players where discord_id=actor) then raise exception '測試身分已存在，停止驗證';end if;
 insert into qiunai_staff(discord_id,display_name,allowed_services)values(actor,'主題驗證','[]');
 insert into players(discord_id,display_name)values(actor,'主題驗證');
 insert into users(user_id,coins)values(actor,100);
 insert into salary_wallet_entries(app_key,discord_id,entry_type,amount,source_table,source_id,settlement_date,metadata)values('qiunai',actor,'staff_bonus',100,'hr_theme_fixture','q',current_date,'{}'),('deepnight',actor,'staff_bonus',100,'hr_theme_fixture','d',current_date,'{}');
 begin perform hr_apply_theme(actor,'white');raise exception 'UNPAID_ALLOWED';exception when others then if sqlerrm='UNPAID_ALLOWED' then raise;end if;end;
 insert into hr_theme_verification values('unpaid themes cannot be applied',true);
 result:=hr_buy_theme_atomic(actor,'white','asd',order_a);
 if result->>'status'<>'paid' or (select coins from users where user_id=actor)<>90 or (select count(*) from hr_theme_entitlements where discord_id=actor and theme_key='white')<>1 then raise exception 'ASD purchase failed';end if;
 insert into hr_theme_verification values('ASD debit, payment and entitlement commit together',true);
 perform hr_buy_theme_atomic(actor,'white','asd',order_a);
 perform hr_buy_theme_atomic(actor,'white','asd','00000000-0000-4000-8000-000000001003');
 if (select coins from users where user_id=actor)<>90 or (select count(*) from wallet_logs where user_id=actor)<>1 then raise exception 'duplicate debit';end if;
 insert into hr_theme_verification values('request replay and owned purchase do not debit again',true);
 begin perform hr_buy_theme_atomic(other_actor,'white','asd',order_a);raise exception 'CROSS_OWNER_ALLOWED';exception when others then if sqlerrm='CROSS_OWNER_ALLOWED' then raise;end if;end;
 insert into hr_theme_verification values('request identifiers are bound to their buyer',true);
 result:=hr_buy_theme_atomic(actor,'black','salary',order_b,'qiunai');
 if result->>'status'<>'paid' or (select sum(amount) from salary_wallet_entries where app_key='qiunai' and discord_id=actor)<>90 or (select count(*) from qiunai_staff_bonus where discord_id=actor and amount=-10 and wallet_settled_at is not null)<>1 then raise exception 'salary debit failed';end if;
 perform hr_buy_theme_atomic(actor,'black','salary',order_b,'qiunai');
 if (select count(*) from qiunai_staff_bonus where discord_id=actor)<>1 then raise exception 'salary debit replay';end if;
 insert into hr_theme_verification values('Qiunai salary deduction is settled once and recorded as a deduction',true);
 perform hr_buy_theme_atomic(actor,'gray','salary','00000000-0000-4000-8000-000000001004','deepnight');
 if (select sum(amount) from salary_wallet_entries where app_key='deepnight' and discord_id=actor)<>90 or (select count(*) from players_bonus where discord_id=actor and amount=-10 and wallet_settled_at is not null)<>1 then raise exception 'DeepNight deduction failed';end if;
 insert into hr_theme_verification values('DeepNight deduction stays in its department ledger',true);
 update users set coins=5 where user_id=actor;
 begin perform hr_buy_theme_atomic(actor,'blue','asd','00000000-0000-4000-8000-000000001005');raise exception 'OVERDRAFT_ALLOWED';exception when others then if sqlerrm='OVERDRAFT_ALLOWED' then raise;end if;end;
 if (select coins from users where user_id=actor)<>5 or exists(select 1 from hr_theme_orders where id='00000000-0000-4000-8000-000000001005') then raise exception 'failed debit mutated state';end if;
 insert into hr_theme_verification values('insufficient ASD leaves money, order and entitlement unchanged',true);
 update hr_theme_catalog set sale_ends_at=now()-interval '1 second' where key='halloween-2026';
 begin perform hr_buy_theme_atomic(actor,'halloween-2026','asd','00000000-0000-4000-8000-000000001006');raise exception 'CLOSED_SALE_ALLOWED';exception when others then if sqlerrm='CLOSED_SALE_ALLOWED' then raise;end if;end;
 insert into hr_theme_verification values('Halloween stops accepting purchases after its sale deadline',true);
 update hr_theme_catalog set sale_ends_at=now()+interval '1 day' where key='halloween-2026';update users set coins=100 where user_id=actor;
 result:=hr_buy_theme_atomic(actor,'halloween-2026','asd','00000000-0000-4000-8000-000000001007');
 if (select coins from users where user_id=actor)<>50 or (result->>'amount')::integer<>50 then raise exception 'Halloween price wrong';end if;
 update hr_theme_catalog set sale_ends_at=now()-interval '1 second' where key='halloween-2026';perform hr_apply_theme(actor,'halloween-2026');
 if (select theme_key from hr_theme_preferences where discord_id=actor)<>'halloween-2026' then raise exception 'owned Halloween expired';end if;
 insert into hr_theme_verification values('Halloween costs 50 and remains usable after the sale closes',true);
 result:=hr_buy_theme_atomic(actor,'pink','ecpay','00000000-0000-4000-8000-000000001008',null,'TESTMERCHANT','HT000000000000000001','test@example.com');
 if result->>'status'<>'pending' or (result->>'amount')::integer<>10 then raise exception 'pending order wrong';end if;
 begin perform hr_apply_theme(actor,'pink');raise exception 'PENDING_UNLOCKED';exception when others then if sqlerrm='PENDING_UNLOCKED' then raise;end if;end;
 insert into hr_theme_verification values('a pending ECPay order does not unlock the theme',true);
 begin perform hr_complete_theme_payment('HT000000000000000001','WRONG','GATEWAY1',10);raise exception 'WRONG_MERCHANT_ALLOWED';exception when others then if sqlerrm='WRONG_MERCHANT_ALLOWED' then raise;end if;end;
 begin perform hr_complete_theme_payment('HT000000000000000001','TESTMERCHANT','GATEWAY1',1);raise exception 'WRONG_AMOUNT_ALLOWED';exception when others then if sqlerrm='WRONG_AMOUNT_ALLOWED' then raise;end if;end;
 if exists(select 1 from hr_theme_entitlements where discord_id=actor and theme_key='pink') then raise exception 'invalid callback unlocked';end if;
 insert into hr_theme_verification values('merchant and amount mismatches cannot fulfill a payment',true);
 perform hr_complete_theme_payment('HT000000000000000001','TESTMERCHANT','GATEWAY1',10);
 perform hr_complete_theme_payment('HT000000000000000001','TESTMERCHANT','GATEWAY1',10);
 perform hr_apply_theme(actor,'pink');
 if (select count(*) from hr_theme_entitlements where discord_id=actor and theme_key='pink')<>1 then raise exception 'callback replay';end if;
 insert into hr_theme_verification values('verified callbacks unlock once; notification replays are idempotent',true);
 result:=hr_buy_theme_atomic(actor,'blue','ecpay','00000000-0000-4000-8000-000000001009',null,'TESTMERCHANT','HT000000000000000002','test@example.com');
 result:=hr_buy_theme_atomic(actor,'blue','ecpay','00000000-0000-4000-8000-000000001010',null,'TESTMERCHANT','HT000000000000000003','test@example.com');
 if result->>'id'<>'00000000-0000-4000-8000-000000001009' or (select count(*) from hr_theme_orders where discord_id=actor and theme_key='blue')<>1 then raise exception 'duplicate pending payment';end if;
 update hr_theme_orders set status='cancelled' where id='00000000-0000-4000-8000-000000001009';
 begin perform hr_complete_theme_payment('HT000000000000000002','TESTMERCHANT','GATEWAY2',10);raise exception 'CANCELLED_GRANTED';exception when others then if sqlerrm='CANCELLED_GRANTED' then raise;end if;end;
 insert into hr_theme_verification values('pending checkout is reused and cancelled orders cannot unlock',true);
 update salary_wallet_entries set amount=15 where app_key='qiunai' and discord_id=actor and source_table='hr_theme_fixture';
 begin perform hr_buy_theme_atomic(actor,'blue','salary','00000000-0000-4000-8000-000000001011','qiunai');raise exception 'SALARY_OVERDRAWN';exception when others then if sqlerrm='SALARY_OVERDRAWN' then raise;end if;end;
 if (select sum(amount) from salary_wallet_entries where app_key='qiunai' and discord_id=actor)<>5 or exists(select 1 from hr_theme_orders where id='00000000-0000-4000-8000-000000001011') then raise exception 'insufficient salary changed money';end if;
 insert into hr_theme_verification values('insufficient salary never creates a debit or entitlement',true);
 if has_function_privilege('anon','hr_buy_theme_atomic(text,text,text,uuid,text,text,text,text)','execute') or has_function_privilege('authenticated','hr_complete_theme_payment(text,text,text,integer)','execute') or has_table_privilege('authenticated','hr_theme_entitlements','insert') then raise exception 'browser role can forge purchases';end if;
 insert into hr_theme_verification values('browser database roles cannot mint purchases or entitlements',true);
 if (select count(*) from hr_theme_catalog where key in('white','black','blue','gray','pink') and price=10 and sale_ends_at is null)<>5 then raise exception 'pure color catalog wrong';end if;
 insert into hr_theme_verification values('all five pure color themes cost 10 with no sale end',true);
end $test$;
select * from hr_theme_verification;
rollback;
